-- Гилнеас, осада города (#32112): фаза 170 после сдачи задания "Блокада!", прыжки воргенов и пост стражи.
-- Источник: issue TrinityCore #32112, ревизия 7407dd21f071; патч протестирован в игре.
-- Сверено с TDB_full_world_1210.26091 и живой БД: задания 14078/14099, зоны 4714/4755/4757,
-- заклинание 59073, NPC 34884/34916/34913, фаза 170, спавны Jump1-Jump12 и сценарии 3488400-3488411,
-- условия SourceGroup 3-14; конфликтов в sql/updates нет.
-- Старые сценарии на событии сброса заменяются однократным запуском при возрождении; удаления перед вставками сохранены.

-- VERIFY (новые ID, отсутствовавшие в TDB 1210 и sql/updates до этого обновления):
--   creature 11800210-11800218 и StringId Jump13-Jump21;
--   сценарии 3488412-3488420 и условия SourceGroup 15-23;
--   остальные ID, спавны, задания, зоны, фаза и заклинание подтверждены TDB и живой БД.

SET @CGUID := 11800210;

-- Фаза 170 действует во всём городе с момента сдачи задания "Блокада!", а не только на Торговой площади
UPDATE `spell_area` SET `quest_start`=14078, `quest_start_status`=64 WHERE `spell`=59073 AND `area` IN (4714,4755,4757) AND `quest_start`=14099;

-- Городская стража Гилнеаса: 30-й пост; буйствующие воргены: отсутствующие в TDB точки прыжков (Jump13-Jump20)
DELETE FROM `creature` WHERE `guid` BETWEEN @CGUID+0 AND @CGUID+8 AND `id` IN (34916,34884);

DELETE FROM `creature_addon` WHERE `guid` IN (@CGUID+0, 3000060, 3000062);

-- Буйствующий ворген: четвёртый нападающий у лавки возвращён на своё место
UPDATE `creature` SET `position_x`=-1497.306, `position_y`=1439.811, `position_z`=36.055, `orientation`=0.82 WHERE `guid`=3000063;

-- Буйствующий ворген: StringId для наземного спавна за северными домами
UPDATE `creature` SET `StringId`='Jump21' WHERE `guid`=3000058;

-- Буйствующий ворген: прыжок выполняется один раз за спавн (On Respawn срабатывает при загрузке ячейки и при возрождении), а не при каждом сбросе/убегании
DELETE FROM `smart_scripts` WHERE `entryorguid`=34884 AND `source_type`=0 AND `id` BETWEEN 2 AND 22;

DELETE FROM `smart_scripts` WHERE `entryorguid` BETWEEN 3488400 AND 3488420 AND `source_type`=9;

DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId`=22 AND `SourceEntry`=34884 AND `SourceId`=0 AND `SourceGroup` BETWEEN 3 AND 23;

-- Принц Лиам Греймайн: боевой клик группы каждые 20-24 с, первый через 5-20 с, вне боя молчит
DELETE FROM `smart_scripts` WHERE `entryorguid`=34913 AND `source_type`=0 AND `id`=0;
